- [ ] MRL truncation with re-normalization at all supported dims
- [ ] Baseline metrics: load time, throughput, memory at each dim level
- [ ] Speed claim verified against transformer baseline
- [ ] Tests cover full dimension range and edge cases
- [ ] E2E script logs complete MRL analysis

## Task: Define Benchmark Metrics

Create the core metric definitions and collection framework for the bake-off.
These structs are used by bd-120 (runner) which populates `BenchmarkResult`,
and by bd-5fj3 (report) which consumes the results.

## Deliverables

### 1) Metric Struct Definitions
```rust
// src/benchmark/metrics.rs

/// Speed metrics collected during benchmark runs
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct SpeedMetrics {
    pub cold_start_ms: f64,          // Time to load model + first embed
    pub warm_latency_p50_ms: f64,    // 50th percentile of warm iterations
    pub warm_latency_p95_ms: f64,    // 95th percentile
    pub warm_latency_p99_ms: f64,    // 99th percentile
    pub warm_latency_max_ms: f64,    // Maximum observed latency
    pub throughput_docs_per_sec: f64, // Average throughput (batch_size / mean_latency)
    pub time_to_first_result_ms: f64, // Cold start + first inference
    pub jitter_cv: f64,              // Coefficient of variation (std/mean)
}

/// Quality metrics computed against ground truth corpus (from bd-cy0)
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct QualityMetrics {
    pub ndcg_at_10: f64,       // Primary quality metric
    pub mrr_at_10: f64,        // Mean Reciprocal Rank
    pub map_at_10: f64,        // Mean Average Precision
    pub recall_at_100: f64,    // Recall in top-100
    pub precision_at_10: f64,  // Precision in top-10
}
```

### 2) Metric Computation Functions
```rust
/// Compute NDCG@K (Normalized Discounted Cumulative Gain)
pub fn ndcg_at_k(ranked_relevances: &[f64], k: usize) -> f64 {
    let dcg: f64 = ranked_relevances.iter()
        .take(k)
        .enumerate()
        .map(|(i, &rel)| (2f64.powf(rel) - 1.0) / (i as f64 + 2.0).log2())
        .sum();

    // Ideal DCG: sort relevances descending
    let mut ideal = ranked_relevances.to_vec();
    ideal.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
    let idcg: f64 = ideal.iter()
        .take(k)
        .enumerate()
        .map(|(i, &rel)| (2f64.powf(rel) - 1.0) / (i as f64 + 2.0).log2())
        .sum();

    if idcg == 0.0 { 0.0 } else { dcg / idcg }
}

/// Compute MRR (Mean Reciprocal Rank)
pub fn mrr(ranked_relevances: &[f64], threshold: f64) -> f64 {
    for (i, &rel) in ranked_relevances.iter().enumerate() {
        if rel >= threshold {
            return 1.0 / (i as f64 + 1.0);
        }
    }
    0.0
}

/// Compute MAP@K (Mean Average Precision)
pub fn map_at_k(ranked_relevances: &[f64], k: usize, threshold: f64) -> f64 {
    let mut sum_precision = 0.0;
    let mut relevant_count = 0;

    for (i, &rel) in ranked_relevances.iter().take(k).enumerate() {
        if rel >= threshold {
            relevant_count += 1;
            sum_precision += relevant_count as f64 / (i as f64 + 1.0);
        }
    }

    let total_relevant = ranked_relevances.iter().filter(|&&r| r >= threshold).count();
    if total_relevant == 0 { 0.0 } else { sum_precision / total_relevant as f64 }
}

/// Compute percentile from sorted latency measurements
pub fn percentile(values: &[Duration], p: f64) -> f64 {
    assert!(!values.is_empty());
    assert!((0.0..=1.0).contains(&p));
    let mut sorted: Vec<f64> = values.iter().map(|d| d.as_secs_f64() * 1000.0).collect();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let idx = ((sorted.len() - 1) as f64 * p).round() as usize;
    sorted[idx]
}

/// Coefficient of variation (jitter measure)
pub fn coefficient_of_variation(values: &[Duration]) -> f64 {
    let ms: Vec<f64> = values.iter().map(|d| d.as_secs_f64() * 1000.0).collect();
    let mean = ms.iter().sum::<f64>() / ms.len() as f64;
    if mean == 0.0 { return 0.0; }
    let variance = ms.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / ms.len() as f64;
    variance.sqrt() / mean
}

/// Bootstrap confidence interval (used by bd-2ep for significance testing)
pub fn bootstrap_ci(
    values: &[f64],
    n_bootstrap: usize,
    confidence: f64,
) -> (f64, f64) {
    let mut rng = SmallRng::seed_from_u64(42);  // Deterministic for reproducibility
    let n = values.len();
    let mut means = Vec::with_capacity(n_bootstrap);

    for _ in 0..n_bootstrap {
        let sample_mean: f64 = (0..n)
            .map(|_| values[rng.gen_range(0..n)])
            .sum::<f64>() / n as f64;
        means.push(sample_mean);
    }

    means.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let alpha = (1.0 - confidence) / 2.0;
    let lo_idx = (alpha * means.len() as f64).floor() as usize;
    let hi_idx = ((1.0 - alpha) * means.len() as f64).ceil() as usize;
    (means[lo_idx], means[hi_idx.min(means.len() - 1)])
}
```

### 3) Evaluation Pipeline Helper
```rust
/// Evaluate an embedder against the ground truth corpus
/// Returns QualityMetrics averaged across all queries
pub fn evaluate_quality(
    embedder: &dyn Embedder,
    corpus: &Corpus,
    top_k: usize,
) -> Result<QualityMetrics> {
    let mut ndcg_scores = Vec::new();
    let mut mrr_scores = Vec::new();
    let mut map_scores = Vec::new();
    let mut recall_scores = Vec::new();
    let mut precision_scores = Vec::new();

    // Embed all corpus documents
    let doc_texts: Vec<&str> = corpus.documents.iter().map(|d| d.text.as_str()).collect();
    let doc_embeddings = embedder.embed_batch(&doc_texts)?;

    for query in &corpus.queries {
        let query_emb = embedder.embed_batch(&[query.text.as_str()])?;
        let query_vec = &query_emb[0];

        // Compute cosine similarities (embeddings are normalized, so dot product)
        let mut scores: Vec<(usize, f64)> = doc_embeddings.iter()
            .enumerate()
            .map(|(i, doc_emb)| {
                let sim = dot_product(query_vec, doc_emb);
                (i, sim as f64)
            })
            .collect();
        scores.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());

        // Map to relevance judgments
        let ranked_rels: Vec<f64> = scores.iter()
            .take(top_k.max(100))
            .map(|(idx, _)| {
                let doc_id = &corpus.documents[*idx].id;
                query.relevants.get(doc_id).copied().unwrap_or(0.0)
            })
            .collect();

        ndcg_scores.push(ndcg_at_k(&ranked_rels, 10));
        mrr_scores.push(mrr(&ranked_rels, 1.0));
        map_scores.push(map_at_k(&ranked_rels, 10, 1.0));
        recall_scores.push(recall_at_k(&ranked_rels, 100, 1.0));
        precision_scores.push(precision_at_k(&ranked_rels, 10, 1.0));
    }

    Ok(QualityMetrics {
        ndcg_at_10: mean(&ndcg_scores),
        mrr_at_10: mean(&mrr_scores),
        map_at_10: mean(&map_scores),
        recall_at_100: mean(&recall_scores),
        precision_at_10: mean(&precision_scores),
    })
}
```

