## File: src/output/stats.rs

### Number Formatting Utilities
```rust
/// Format a number with thousands separators
pub fn format_number(n: u64) -> String {
    let s = n.to_string();
    let mut result = String::with_capacity(s.len() + s.len() / 3);

    for (i, c) in s.chars().enumerate() {
        if i > 0 && (s.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

/// Format bytes as human-readable (KB, MB, GB)
pub fn humanize_bytes(bytes: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = KB * 1024;
    const GB: u64 = MB * 1024;
    const TB: u64 = GB * 1024;

    if bytes >= TB {
        format!("{:.2} TB", bytes as f64 / TB as f64)
    } else if bytes >= GB {
        format!("{:.2} GB", bytes as f64 / GB as f64)
    } else if bytes >= MB {
        format!("{:.2} MB", bytes as f64 / MB as f64)
    } else if bytes >= KB {
        format!("{:.2} KB", bytes as f64 / KB as f64)
    } else {
        format!("{} B", bytes)
    }
}

/// Format a percentage
pub fn format_percentage(value: f64, total: f64) -> String {
    if total == 0.0 {
        return "—".to_string();
    }
    format!("{:.1}%", (value / total) * 100.0)
}
```

### Archive Stats Structure
```rust
#[derive(Default, Clone, Debug)]
pub struct ArchiveStats {
    pub tweet_count: u64,
    pub like_count: u64,
    pub dm_count: u64,
    pub grok_count: u64,
    pub total_documents: u64,

    pub archive_size_bytes: u64,
    pub index_size_bytes: u64,
    pub database_size_bytes: u64,

    pub date_range_start: Option<DateTime<Utc>>,
    pub date_range_end: Option<DateTime<Utc>>,

    pub index_last_updated: Option<DateTime<Utc>>,
    pub index_doc_count: u64,
    pub embedding_count: u64,

    pub archive_path: PathBuf,
}

impl ArchiveStats {
    pub fn total_size_bytes(&self) -> u64 {
        self.archive_size_bytes + self.index_size_bytes + self.database_size_bytes
    }

    pub fn is_index_stale(&self) -> bool {
        self.index_doc_count < self.total_documents
    }

    pub fn index_coverage_pct(&self) -> f64 {
        if self.total_documents == 0 {
            return 100.0;
        }
        (self.index_doc_count as f64 / self.total_documents as f64) * 100.0
    }
}
