pub enum SearchMode {
    Hybrid,
    Lexical,
    Semantic,
}

impl std::fmt::Display for SearchMode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Hybrid => write!(f, "hybrid"),
            Self::Lexical => write!(f, "lexical"),
            Self::Semantic => write!(f, "semantic"),
        }
    }
}

impl Default for SearchMode {
    fn default() -> Self {
        Self::Hybrid
    }
}
