    let irrelevant = embedder.embed("chocolate cake baking recipe").unwrap();

    let mut prev_margin = f64::MAX;
    for dims in [64, 128, 256, 512, 768] {
        let qt = embedder.truncate(&[query.clone()], dims).unwrap();
        let rt = embedder.truncate(&[relevant.clone()], dims).unwrap();
        let it = embedder.truncate(&[irrelevant.clone()], dims).unwrap();

        let sim_good = cosine_similarity(&qt[0], &rt[0]);
        let sim_bad = cosine_similarity(&qt[0], &it[0]);
        let margin = (sim_good - sim_bad) as f64;

        tracing::info!(dims = dims, sim_relevant = sim_good, sim_irrelevant = sim_bad, margin = margin,
            "MRL quality at reduced dimensions");

        // Relevance ordering should be preserved at all dimensions
        assert!(sim_good > sim_bad,
            "Ordering broken at dims={}: relevant={} vs irrelevant={}", dims, sim_good, sim_bad);
    }
}

