        .theme(theme.clone())
        .add_column(
            TableColumn::new("Date", |d| d.date.format("%Y-%m-%d").to_string())
        )
        .add_column(
            TableColumn::new("Tweets", |d| d.tweet_count.to_string())
                .justify(JustifyMethod::Right)
        )
        .add_column(
            TableColumn::new("Likes", |d| d.like_count.to_string())
                .justify(JustifyMethod::Right)
        )
        .add_column(
