                .justify(JustifyMethod::Right)
        )
        .add_column(
            TableColumn::new("Total", |d| d.total().to_string())
                .justify(JustifyMethod::Right)
                .sortable(|d| d.total() as i64)
        )
        .sort_by(4, true); // Sort by total descending

