#[test]
fn test_mrl_latency_decreases_with_fewer_dims() {
    let corpus = load_test_corpus_medium(); // 1000 docs
    let query = "machine learning optimization";

    let mut latencies: Vec<(usize, f64)> = Vec::new();

    for dims in [128, 256, 512, 768] {
        let index = build_index_with_dims(&corpus, "nomic", dims).unwrap();

        // Warmup
        for _ in 0..3 { index.search(query, SearchOpts::semantic()).unwrap(); }

        let start = Instant::now();
        for _ in 0..50 {
            index.search(query, SearchOpts::semantic()).unwrap();
        }
        let avg_ms = start.elapsed().as_millis() as f64 / 50.0;
        latencies.push((dims, avg_ms));

        tracing::info!(dims = dims, avg_ms = avg_ms, "MRL latency at dimension");
    }

    // Lower dims should generally be faster
    let (first_dims, first_latency) = latencies.first().unwrap();
    let (last_dims, last_latency) = latencies.last().unwrap();
    tracing::info!(
        low_dims = first_dims, low_ms = first_latency,
        high_dims = last_dims, high_ms = last_latency,
        speedup = last_latency / first_latency,
        "MRL latency speedup"
    );
}
