### Doctor Report Structure
```rust
use std::time::{Duration, Instant};
use crate::output::{Output, Theme};
use rich_rust::prelude::*;

pub struct DoctorReport {
    checks: Vec<DiagnosticCheck>,
    theme: Theme,
    overall_status: HealthStatus,
}

#[derive(Clone, Default)]
pub struct DiagnosticCheck {
    pub name: String,
    pub category: DiagnosticCategory,
    pub status: HealthStatus,
    pub message: String,
    pub details: Option<String>,
    pub suggestion: Option<String>,
    pub duration: Duration,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum DiagnosticCategory {
    #[default]
    Archive,
    Index,
    Database,
    Permissions,
    Configuration,
    Performance,
}

impl DiagnosticCategory {
    /// Returns an iterator over all diagnostic categories
    pub fn all() -> impl Iterator<Item = Self> {
        [
            Self::Archive,
            Self::Index,
            Self::Database,
            Self::Permissions,
            Self::Configuration,
            Self::Performance,
        ].into_iter()
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Archive => "Archive",
            Self::Index => "Index",
            Self::Database => "Database",
            Self::Permissions => "Permissions",
            Self::Configuration => "Configuration",
            Self::Performance => "Performance",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum HealthStatus {
    #[default]
    Healthy,
    Warning,
    Error,
    Skipped,
}

impl HealthStatus {
    /// Returns the severity level (higher = worse)
    pub fn severity(&self) -> u8 {
        match self {
            Self::Healthy => 0,
            Self::Skipped => 1,
            Self::Warning => 2,
            Self::Error => 3,
        }
    }
}

impl DoctorReport {
    /// Create a report from a list of completed checks
    pub fn from_checks(checks: Vec<DiagnosticCheck>) -> Self {
        let overall_status = Self::compute_overall_status(&checks);
        Self {
            checks,
            theme: Theme::default(),
            overall_status,
        }
    }

    /// Create a report with a specific theme
    pub fn from_checks_with_theme(checks: Vec<DiagnosticCheck>, theme: Theme) -> Self {
        let overall_status = Self::compute_overall_status(&checks);
        Self {
            checks,
            theme,
            overall_status,
        }
    }

    /// Compute overall status from worst check status
    fn compute_overall_status(checks: &[DiagnosticCheck]) -> HealthStatus {
        checks
            .iter()
            .map(|c| c.status)
            .max_by_key(|s| s.severity())
            .unwrap_or(HealthStatus::Healthy)
    }

    /// Count checks by status: (healthy, warnings, errors)
    fn count_statuses(&self) -> (usize, usize, usize) {
        let healthy = self.checks.iter().filter(|c| c.status == HealthStatus::Healthy).count();
        let warnings = self.checks.iter().filter(|c| c.status == HealthStatus::Warning).count();
        let errors = self.checks.iter().filter(|c| c.status == HealthStatus::Error).count();
        (healthy, warnings, errors)
    }

    /// Collect all suggestions from failed/warning checks
    fn collect_suggestions(&self) -> Vec<String> {
        self.checks
            .iter()
            .filter(|c| c.status != HealthStatus::Healthy && c.status != HealthStatus::Skipped)
            .filter_map(|c| c.suggestion.clone())
            .collect()
    }

    pub fn render(&self, output: &Output) {
        if !output.is_styled() {
            self.render_plain(output);
            return;
        }

        // Title panel
        let title = Panel::from_text(&self.render_summary())
            .title("🩺 xf Doctor")
            .border_style(self.status_color(self.overall_status));
        output.print_renderable(&title);

        // Group checks by category
        for category in DiagnosticCategory::all() {
            let category_checks: Vec<_> = self.checks.iter()
                .filter(|c| c.category == category)
                .collect();

            if !category_checks.is_empty() {
                self.render_category(&category, &category_checks, output);
            }
        }

        // Suggestions panel (if any warnings/errors)
        let suggestions = self.collect_suggestions();
        if !suggestions.is_empty() {
            self.render_suggestions(&suggestions, output);
        }
    }

    fn render_summary(&self) -> String {
        let (healthy, warnings, errors) = self.count_statuses();
        let status_icon = match self.overall_status {
            HealthStatus::Healthy => "✓",
            HealthStatus::Warning => "⚠",
            HealthStatus::Error => "✗",
            HealthStatus::Skipped => "○",
        };

        let status_text = match self.overall_status {
            HealthStatus::Healthy => "All systems healthy",
            HealthStatus::Warning => "Some issues detected",
            HealthStatus::Error => "Problems found",
            HealthStatus::Skipped => "Checks incomplete",
        };

        format!(
            "{} {}\n\nChecks: {} passed, {} warnings, {} errors",
            status_icon, status_text, healthy, warnings, errors
        )
    }

    fn render_category(&self, category: &DiagnosticCategory, checks: &[&DiagnosticCheck], output: &Output) {
        let category_name = category.as_str();
        output.console.rule(Some(&format!("📋 {}", category_name)));

        for check in checks {
            self.render_check(check, output);
        }
    }

    fn render_check(&self, check: &DiagnosticCheck, output: &Output) {
        let icon = match check.status {
            HealthStatus::Healthy => format!("[{}]✓[/]", self.theme.success),
            HealthStatus::Warning => format!("[{}]⚠[/]", self.theme.warning),
            HealthStatus::Error => format!("[{}]✗[/]", self.theme.error),
            HealthStatus::Skipped => format!("[{}]○[/]", self.theme.muted),
        };

        let timing = format!("[{}]({:.1}ms)[/]", self.theme.muted, check.duration.as_secs_f64() * 1000.0);

        let mut line = format!("{} {} {}", icon, check.name, timing);

        if check.status != HealthStatus::Healthy {
            line.push_str(&format!("\n    {}", check.message));
            if let Some(ref details) = check.details {
                line.push_str(&format!("\n    [{}]{}[/]", self.theme.muted, details));
            }
        }

        output.print(&line);
    }

    fn render_suggestions(&self, suggestions: &[String], output: &Output) {
        let panel = Panel::from_text(&format!(
            "[{}]Suggestions:[/]\n{}",
            self.theme.info,
            suggestions.iter()
                .enumerate()
                .map(|(i, s)| format!("  {}. {}", i + 1, s))
                .collect::<Vec<_>>()
                .join("\n")
        ))
        .title("💡 Recommendations")
        .border_style(self.theme.info);

        output.print_renderable(&panel);
    }

    fn status_color(&self, status: HealthStatus) -> Color {
        match status {
            HealthStatus::Healthy => self.theme.success,
            HealthStatus::Warning => self.theme.warning,
            HealthStatus::Error => self.theme.error,
            HealthStatus::Skipped => self.theme.muted,
        }
    }

    fn render_plain(&self, _output: &Output) {
        let (healthy, warnings, errors) = self.count_statuses();

        println!("xf Doctor Report");
        println!("================");
        println!("Status: {} passed, {} warnings, {} errors", healthy, warnings, errors);
        println!();

        for check in &self.checks {
            let status_char = match check.status {
                HealthStatus::Healthy => "[OK]",
                HealthStatus::Warning => "[WARN]",
                HealthStatus::Error => "[FAIL]",
                HealthStatus::Skipped => "[SKIP]",
            };
            println!("{} {} ({:.1}ms)", status_char, check.name, check.duration.as_secs_f64() * 1000.0);
            if check.status != HealthStatus::Healthy {
                println!("    {}", check.message);
                if let Some(ref suggestion) = check.suggestion {
                    println!("    -> {}", suggestion);
                }
            }
        }
    }
}
