impl DoctorReport {
    pub fn run_all_checks(config: &Config) -> Self {
        let mut checks = vec![];

        // Archive checks
        checks.push(Self::check_archive_exists(config));
        checks.push(Self::check_archive_readable(config));
        checks.push(Self::check_archive_structure(config));

        // Index checks
        checks.push(Self::check_index_exists(config));
        checks.push(Self::check_index_fresh(config));
        checks.push(Self::check_index_integrity(config));

        // Database checks
        checks.push(Self::check_database_connection(config));
        checks.push(Self::check_database_schema(config));

        // Performance checks
        checks.push(Self::check_index_size(config));
        checks.push(Self::check_query_performance(config));

        Self::from_checks(checks)
    }

    fn check_archive_exists(config: &Config) -> DiagnosticCheck {
        let start = Instant::now();
        let exists = config.archive_path.exists();

        DiagnosticCheck {
            name: "Archive exists".into(),
            category: DiagnosticCategory::Archive,
            status: if exists { HealthStatus::Healthy } else { HealthStatus::Error },
            message: if exists {
                "Archive found".into()
            } else {
                format!("Archive not found at: {}", config.archive_path.display())
            },
            details: None,
            suggestion: if !exists {
                Some("Run 'xf init' or specify archive path with --archive".into())
            } else {
                None
            },
            duration: start.elapsed(),
        }
    }

    fn check_archive_readable(config: &Config) -> DiagnosticCheck {
        let start = Instant::now();
        let readable = std::fs::metadata(&config.archive_path)
            .map(|m| m.permissions().readonly() == false)
            .unwrap_or(false);

        DiagnosticCheck {
            name: "Archive readable".into(),
            category: DiagnosticCategory::Archive,
            status: if readable { HealthStatus::Healthy } else { HealthStatus::Error },
            message: if readable { "Archive is readable".into() } else { "Archive is not readable".into() },
            details: None,
            suggestion: if !readable { Some("Check file permissions".into()) } else { None },
            duration: start.elapsed(),
        }
    }

