            name: "Archive structure".into(),
            category: DiagnosticCategory::Archive,
            status: if data_js_exists { HealthStatus::Healthy } else { HealthStatus::Warning },
            message: if data_js_exists { "Archive structure valid".into() } else { "Archive structure incomplete".into() },
            details: None,
            suggestion: if !data_js_exists { Some("Ensure archive contains a 'data' directory".into()) } else { None },
