## Implementation
```rust
// src/report/generate.rs
use crate::benchmark::runner::BenchmarkResult;
use crate::models::ModelCategory;

pub fn generate_report(
    benchmark_results: &[BenchmarkResult],
    reranker_results: &RerankQualityReport,  // from bd-2ep
) -> Result<BakeoffReport> {
    // 1. Split by category using BenchmarkResult.category
    let static_models: Vec<_> = benchmark_results.iter()
        .filter(|r| r.category == ModelCategory::StaticEmbedder)
        .collect();
    let transformer_models: Vec<_> = benchmark_results.iter()
        .filter(|r| r.category == ModelCategory::TransformerEmbedder)
        .collect();

    // 2. Filter to eligible + reliable
    let eligible_static: Vec<_> = static_models.iter()
        .filter(|r| r.eligible && r.is_reliable())
        .copied().collect();
    let eligible_transformer: Vec<_> = transformer_models.iter()
        .filter(|r| r.eligible && r.is_reliable())
        .copied().collect();

    let baselines: Vec<_> = benchmark_results.iter()
        .filter(|r| !r.eligible)
        .collect();

    tracing::info!(
        static_eligible = eligible_static.len(),
        transformer_eligible = eligible_transformer.len(),
        baselines = baselines.len(),
        "Filtered models by eligibility and reliability"
    );

    // 3. Compute Pareto frontiers per category
    let static_frontier = pareto_frontier(&eligible_static);
    let transformer_frontier = pareto_frontier(&eligible_transformer);

    // 4. Select winners (highest overall score on Pareto frontier)
    let static_winner = select_winner(&eligible_static, &static_frontier)?;
    let transformer_winner = select_winner(&eligible_transformer, &transformer_frontier)?;
    let reranker_winner = select_reranker_winner(reranker_results)?;

    // 5. Generate report sections
    Ok(BakeoffReport {
        timestamp: Utc::now(),
        static_winner,
        transformer_winner,
        reranker_winner,
        pareto_analysis: generate_pareto_section(benchmark_results),
        latency_analysis: generate_latency_section(benchmark_results),
        reliability: generate_reliability_section(benchmark_results),
        cpu_friendliness: generate_cpu_section(benchmark_results),
        fallback_plan: generate_fallback_section(&static_winner, &transformer_winner),
        baselines: generate_baseline_section(&baselines),
        raw_data: benchmark_results.to_vec(),
    })
}

fn select_winner(models: &[&BenchmarkResult], frontier: &[usize]) -> Result<BakeoffWinner> {
    let best_idx = frontier.iter()
        .max_by(|&&a, &&b| {
            let ma = WinnerMetrics::from_benchmark_result(models[a]);
            let mb = WinnerMetrics::from_benchmark_result(models[b]);
            compute_overall_score(&ma).partial_cmp(&compute_overall_score(&mb))
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .copied()
        .ok_or_else(|| anyhow::anyhow!("No eligible models on Pareto frontier"))?;

    let winner = models[best_idx];
    let metrics = WinnerMetrics::from_benchmark_result(winner);
    Ok(BakeoffWinner {
        category: winner.category.into(),
        model: winner.model_name.clone(),
        pareto_rank: 1,
        overall_score: compute_overall_score(&metrics),
        metrics,
        vs_baseline: compute_baseline_comparison(winner, models)?,
    })
}
