log_pass() {
    local msg="$1"
    ((PASS_COUNT++)) || true
    echo "  ✓ PASS: $msg" | tee -a "$SUMMARY_LOG" "$DETAIL_LOG"
}

log_fail() {
    local msg="$1"
    ((FAIL_COUNT++)) || true
    echo "  ✗ FAIL: $msg" | tee -a "$SUMMARY_LOG" "$DETAIL_LOG"
}

log_warn() {
    local msg="$1"
    ((WARN_COUNT++)) || true
    echo "  ⚠ WARN: $msg" | tee -a "$SUMMARY_LOG" "$DETAIL_LOG"
}

log_skip() {
    local msg="$1"
    ((SKIP_COUNT++)) || true
    echo "  ○ SKIP: $msg" | tee -a "$SUMMARY_LOG" "$DETAIL_LOG"
}

check_no_ansi() {
    local input="$1"
    local context="$2"
    if echo "$input" | grep -qP '\x1b\['; then
        log_fail "$context: Found ANSI escape codes in output"
        return 1
    fi
    return 0
}

