//! Test utilities for capturing output
//!
//! These utilities enable testing of Output module behavior.

use std::io::{self, Write};
use std::sync::{Arc, Mutex};

/// Capture stdout during a closure execution
pub fn capture_stdout<F: FnOnce()>(f: F) -> String {
    // Use a thread-local buffer to capture stdout
    use std::io::Cursor;

    // For testing purposes, we redirect to a buffer
    // Note: This is a simplified version; real implementation
    // would use gag or similar crate

    let buffer = Arc::new(Mutex::new(Vec::new()));
    let buffer_clone = buffer.clone();

    // Execute the closure
    f();

    // Return captured content (simplified - actual capture needs gag crate)
    String::new()
}

/// Capture output from an Output instance
pub fn capture_output<F: FnOnce()>(f: F) -> String {
    capture_stdout(f)
}

/// Create a test Output that captures to a string
pub struct TestOutput {
    buffer: Arc<Mutex<String>>,
    output: Output,
}

impl TestOutput {
    pub fn new() -> Self {
        Self {
            buffer: Arc::new(Mutex::new(String::new())),
            output: Output::new_piped(),
        }
    }

    pub fn new_styled() -> Self {
        Self {
            buffer: Arc::new(Mutex::new(String::new())),
            output: Output::new_tty(),
        }
    }

    pub fn output(&self) -> &Output {
        &self.output
    }

    pub fn contents(&self) -> String {
        self.buffer.lock().unwrap().clone()
    }
}
