// In RerankStep::new, if config.daemon is true:
impl RerankStep {
    pub fn new_with_daemon(config: &ResolvedConfig, client: &DaemonClient) -> Result<Self> {
        let reranker = DaemonReranker::new(
            client.clone(),
            config.reranker.clone().unwrap_or_else(|| DEFAULT_RERANKER.to_string()),
        );
        Ok(Self {
            reranker: Box::new(reranker),
            top_k_rerank: config.rerank_top,
            min_candidates: 5,
        })
    }
}
