fn test_rerank_reorders_candidates() {
    let reranker = MockReranker::with_scores(vec![0.3, 0.9, 0.5]);
    let step = RerankStep { reranker: Box::new(reranker), top_k_rerank: 100, min_candidates: 2 };
    let mut candidates = vec![
        SearchResult { score: 0.9, text: "A".into(), ..default() },
        SearchResult { score: 0.8, text: "B".into(), ..default() },
        SearchResult { score: 0.7, text: "C".into(), ..default() },
    ];
    step.rerank("query", &mut candidates).unwrap();
    assert_eq!(candidates[0].text, "B");  // 0.9 rerank score → first
    assert_eq!(candidates[1].text, "C");  // 0.5 rerank score → second
    assert_eq!(candidates[2].text, "A");  // 0.3 rerank score → third
}

