    // When rerank scores are equal, original score breaks ties
    let reranker = MockReranker::with_scores(vec![0.5, 0.5]);
    let step = RerankStep { reranker: Box::new(reranker), top_k_rerank: 100, min_candidates: 1 };
    let mut candidates = vec![
        SearchResult { score: 0.9, text: "Higher-original".into(), ..default() },
        SearchResult { score: 0.7, text: "Lower-original".into(), ..default() },
    ];
    step.rerank("query", &mut candidates).unwrap();
    assert_eq!(candidates[0].text, "Higher-original"); // Higher original score wins tie
}

#[test]
fn test_reranker_error_propagates() {
    let reranker = MockReranker::failing();
    let step = RerankStep { reranker: Box::new(reranker), top_k_rerank: 100, min_candidates: 1 };
    let mut candidates = vec![make_result("A"), make_result("B")];
    assert!(step.rerank("query", &mut candidates).is_err());
